#!/usr/bin/env python3
"""offer_oct28.py | freepracticesat.com | Oct 28, 2026
Adds offer_followup.js and one script line in index.html (after plan_sample_link.js):
  1. Students who have finished a test see the $29 plan offer on the welcome screen.
  2. "Take your first test" now only shows for students who have never finished one.
  3. Offer views and button clicks are recorded in test_events.
Changes nothing unless index.html looks as expected. Undo: python3 offer_oct28.py --undo"""
import sys,os,json,base64,zlib,hashlib,shutil
C=json.loads('{"anchor": "<script src=\\"plan_sample_link.js?v=20261027\\"></script>", "tag": "<script src=\\"offer_followup.js?v=20261028\\"></script>", "file": "", "fsha": "bc06aec1e0a109ef4900ba86b646b7193193cf97ac5af65214c88ca3875a027d"}')
BK='.offer_backup_20261028'
F='offer_followup.js'
sha=lambda b: hashlib.sha256(b).hexdigest()
rd=lambda p: open(p,'rb').read()
if '--undo' in sys.argv:
    if not os.path.isdir(BK): sys.exit('No backup found. Nothing undone.')
    shutil.copyfile(os.path.join(BK,'index.html'),'index.html')
    if os.path.exists(F): os.rename(F,os.path.join(BK,'removed_'+F))
    print('UNDONE: index.html restored and offer_followup.js removed. Click Republish.'); sys.exit()
idx=rd('index.html')
tag=C['tag'].encode(); anchor=C['anchor'].encode()
if tag in idx and os.path.exists(F) and sha(rd(F))==C['fsha']:
    print('Already done. Nothing to change.'); sys.exit()
bad=[]
if idx.count(anchor)!=1: bad.append('index.html (the plan_sample_link.js line was not found exactly once)')
if tag in idx: bad.append('index.html (already has an offer_followup.js line)')
if os.path.exists(F): bad.append(F+' (already exists)')
if bad:
    print('STOP. Nothing was changed:'); print('\n'.join(bad)); sys.exit(1)
b=zlib.decompress(base64.b64decode(C['file'])); assert sha(b)==C['fsha']
os.makedirs(BK,exist_ok=True)
shutil.copyfile('index.html',os.path.join(BK,'index.html'))
open(F,'wb').write(b)
open('index.html','wb').write(idx.replace(anchor,anchor+b'\n'+tag))
ok=rd('index.html').count(tag)==1 and sha(rd(F))==C['fsha']
print('DONE: welcome-screen offer and click counting added. Click Republish.' if ok else 'CHECK FAILED. Run: python3 offer_oct28.py --undo')
